-- Revisão de 18/11/2026: troca duas obras e traduz os títulos para o português.
-- sorrowful-2-1: a foto mostrava Santa Maria Madalena (anverso) → Duccio, Flagelação (Maestà).
-- joyful-2-4: gravura imprópria como fundo de oração → Ghirlandaio, Visitação (Louvre).
-- O app usa as linhas remotas antes das embutidas. Cada linha exige também o título antigo,
-- para não renomear uma obra caso a ordem da galeria remota seja outra.

update public.images i
set title = v.new_title,
    url = coalesce(v.url, i.url),
    artist = coalesce(v.artist, i.artist),
    description = coalesce(v.description, i.description)
from public.mysteries m,
